data = pd.read_csv('chunks_csv/moran_local_2022_crime.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
data['Crime_value'] = data['Crime_value'].fillna(data['Crime_value'].median())

# Compute neighborhood crime rates
neighborhood_crime_rates = {}
for index, row in data.iterrows():
    neighbors = adjacency[adjacency['borough'] == row['borough']]
    neighbor_crime_rates = []
    for neighbor in neighbors['neighbor']:
        neighbor_crime_rate = data[data['borough'] == neighbor]['Crime_value'].mean()
        neighbor_crime_rates.append(neighbor_crime_rate)
    neighborhood_crime_rates[row['borough']] = np.mean(neighbor_crime_rates)

# Calculate local Moran's I
local_morans_i = {}
for index, row in data.iterrows():
    neighbors = adjacency[adjacency['borough'] == row['borough']]
    neighbor_crime_rates = []
    for neighbor in neighbors['neighbor']:
        neighbor_crime_rate = data[data['borough'] == neighbor]['Crime_value'].mean()
        neighbor_crime_rates.append(neighbor_crime_rate)
    local_morans_i[row['borough']] = np.sum((data['Crime_value'] - data['Crime_value'].mean()) * (neighbor_crime_rates - np.mean(neighbor_crime_rates)))

# Determine hot/cold spot status
hot_cold_spots = {}
for borough, moran_i in local_morans_i.items():
    p_value = np.mean(np.random.choice([-1, 1], size=500, replace=True) * np.random.choice([-1, 1], size=500, replace=True))
