import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/moran_local_2022_crime.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Replace the missing value in the Crime_value column with the median of the non-missing values
data['Crime_value'] = data['Crime_value'].fillna(data['Crime_value'].dropna().median())

# Compute neighborhood crime rates for each borough
neighborhood_crime_rates = {}
for index, row in adjacency.iterrows():
    borough = row['borough']
    neighbors = adjacency.loc[adjacency['neighbor'] == borough, 'borough'].values
    neighborhood_crime_rates[borough] = np.mean(data.loc[data['borough'].isin(neighbors), 'Crime_value'].values)

# Calculate local Moran's I statistic for each borough
local_morans_i = {}
for index, row in data.iterrows():
    borough = row['borough']
    neighborhood_crime_rate = neighborhood_crime_rates[borough]
    local_morans_i[borough] = (row['Crime_value'] - neighborhood_crime_rate) / (data['Crime_value'].std() * (1 + 1 / len(data)))

# Perform permutation test to assess statistical significance
p_values = {}
for borough in local_morans_i:
    permutations = 500
    test_statistic = local_morans_i[borough]
    p_value = 0
    for _ in range(permutations):
        permutation = np.random.permutation(data['Crime_value'])
        permutation_morans_i = (permutation - neighborhood_crime_rates[borough]) / (data['Crime_value'].std() * (1 + 1 / len(data)))
        p_value += np.sum(permutation_morans_i >= test_statistic)
    p_values[borough] = p_value / permutations

# Determine hot/cold spot status
hot_cold_spots = {}
for borough in p_values:
    if p_values[borough] < 0.05:
        if local_morans_i[borough] > 0:
            hot_cold_spots[borough] = 'HH'
        else:
            hot_cold_spots[borough] = 'LL'

# Print the results
data_points_used = len(data)
print(f'data_points_used = {data_points_used}')
if hot_cold_spots:
    print(f'FINAL ANSWER: {", ".join([f"{borough} ({spot}, statistical method={p_value:.4f})" for borough, spot in hot_cold_spots.items()])}')
else:
    print('FINAL ANSWER: none')
